    private void fixture()throws Exception{progress("granting an isolated provider from a separate fixture app UID");shell("am start -n com.nthexperience.desktop.fixture/.GrantActivity --ez reset true");long grantDeadline=SystemClock.uptimeMillis()+12000;boolean granted=false;while(SystemClock.uptimeMillis()<grantDeadline){try{getTargetContext().getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getTargetContext().getContentResolver().takePersistableUriPermission(readOnly,Intent.FLAG_GRANT_READ_URI_PERMISSION);granted=true;break;}catch(SecurityException pending){Thread.sleep(80);}}check(granted,"The isolated provider explicitly grants both fixture roots");DesktopStore store=new DesktopStore(getTargetContext());DocumentFolders.add(store,readOnly,"Nth Read Only");DocumentFolders.add(store,tree,"Nth Test Files");check(DocumentOps.writable(getTargetContext(),doc("root:"),DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE,stat("root:")),"Real prefix grant permits writing the fixture folder");check(!DocumentOps.writable(getTargetContext(),doc("readonly:"),DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE,stat("readonly:")),"Read-only tree has no write grant");}
