openFolder("Nested");awaitFile("Inside.txt");click("Navigate to Nth Test Files");awaitFile("Source.txt");hold(find(v->"Back".equals(v.getContentDescription())));awaitMenu("Navigation history");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);
