    private void boundaries()throws Exception{
        progress("testing interrupted copies, failed verification and unsafe destinations");DocumentOps.Ref source=reference("root:Broken.bin","root:");boolean failed=false;try{DocumentOps.paste(getTargetContext(),Collections.singletonList(source),doc("root:Target"),true,new DocumentOps.Cancel(),s->{});}catch(IOException expected){failed=true;}check(failed&&exists("root:Broken.bin")&&!exists("root:Target/Broken.bin"),"A truncated provider stream cannot delete its original or leave a completed copy");
        DocumentOps.Cancel cancel=new DocumentOps.Cancel();ExecutorService worker=Executors.newSingleThreadExecutor();Future<?> job=worker.submit(()->{try{DocumentOps.paste(getTargetContext(),Collections.singletonList(reference("root:Slow.bin","root:")),doc("root:Target"),true,cancel,s->{});}catch(Exception ignored){}});Thread.sleep(180);cancel.cancel();job.get(12,TimeUnit.SECONDS);worker.shutdown();check(exists("root:Slow.bin")&&!exists("root:Target/Slow.bin"),"Cancelling a partial cut preserves its original and cleans the new partial copy");
        boolean blocked=false;try{DocumentOps.paste(getTargetContext(),Collections.singletonList(reference("root:Nested","root:")),doc("root:Nested"),false,new DocumentOps.Cancel(),s->{});}catch(IOException expected){blocked=true;}check(blocked,"A folder cannot be copied into itself");boolean invalid=false;try{DocumentOps.name("../escape");}catch(IllegalArgumentException expected){invalid=true;}check(invalid,"Names cannot escape a selected folder");boolean denied=false;try{DocumentOps.createFolder(getTargetContext(),doc("readonly:"),"Denied",new DocumentOps.Cancel());}catch(IOException expected){denied=true;}check(denied&&!exists("readonly:Denied"),"Read-only locations reject writes at the operation layer");
        PickerSpec spec=new PickerSpec(new Intent(Intent.ACTION_GET_CONTENT).setType("image/*"));check(spec.accepts("image/png")&&!spec.accepts("text/plain")&&!spec.accepts(DocumentsContract.Document.MIME_TYPE_DIR),"Picker MIME filtering rejects unrelated files and directories");check(getTargetContext().getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).setPackage(BuildConfig.APPLICATION_ID),0).isEmpty(),"Nth does not intercept Android's OPEN_DOCUMENT permission interface");
        ExplorerClipboard.clear();
    }
